from typing import List

def sum_of_subarray_powers(n: int, k: int, a: List[int]) -> int:
    MOD = 998244353
    total_sum = 0
    for l in range(n):
        current_subarray_sum = 0
        for r in range(l, n):
            current_subarray_sum += a[r]
            total_sum += pow(current_subarray_sum, k)
    return total_sum % MOD

