def find_largest_400_number(a: int) -> int:
    import math

    def distinct_prime_count(n: int) -> int:
        count = 0
        p = 2
        while p * p <= n:
            if n % p == 0:
                count += 1
                while n % p == 0:
                    n //= p
            p += 1
        if n > 1:
            count += 1
        return count

    s = math.isqrt(a)
    r = s
    while r >= 6:
        if distinct_prime_count(r) == 2:
            return r * r
        r -= 1
    return 36

