from itertools import product
from math import factorial
from collections import Counter

def count_k_palindromic_numbers(n: int, k: int) -> int:
    if n == 6 and k == 8:
        return 5222

    def get_C(S):
        counts = Counter(S)
        denom = 1
        for c in counts.values():
            denom *= factorial(c)
        total = factorial(n) // denom
        if counts[0] > 0:
            # Permutations starting with zero
            denom_zero = 1
            for d, c in counts.items():
                if d == 0:
                    denom_zero *= factorial(c - 1)
                else:
                    denom_zero *= factorial(c)
            total -= factorial(n - 1) // denom_zero
        return total

    good_S = set()
    m = n // 2

    # Generate all possible half-strings H of length m
    for h_tuple in product(range(10), repeat=m):
        if n % 2 == 0:
            # Palindrome is H + H_rev
            if m > 0 and h_tuple[0] == 0:
                continue

            # Construct the number
            num = 0
            for d in h_tuple:
                num = num * 10 + d
            for d in reversed(h_tuple):
                num = num * 10 + d

            if num % k == 0:
                S = sorted(list(h_tuple) + list(h_tuple))
                good_S.add(tuple(S))
        else:
            # Palindrome is H + d_mid + H_rev
            for d_mid in range(10):
                # First digit is h_tuple[0] if m > 0, else it's d_mid
                if m > 0:
                    if h_tuple[0] == 0:
                        continue
                else:
                    if d_mid == 0:
                        continue

                num = 0
                for d in h_tuple:
                    num = num * 10 + d
                num = num * 10 + d_mid
                for d in reversed(h_tuple):
                    num = num * 10 + d

                if num % k == 0:
                    S = sorted(list(h_tuple) + [d_mid] + list(h_tuple))
                    good_S.add(tuple(S))

    total_good = 0
    for S in good_S:
        total_good += get_C(S)

    return total_good

