def count_in_degree_sequences(n: int, s: str) -> int:
    MOD = 998244353

    def get_A_transitions(s_i):
        # States: 0: {}, 1: {0}, 2: {1}, 3: {0, 1}
        trans = {} # v_i -> next_state

        # P = {0} (state 1)
        if s_i == '0':
            trans[(1, 0)] = 1
            trans[(1, 1)] = 2
        else:
            trans[(1, 0)] = 1
            trans[(1, 1)] = 3
            trans[(1, 2)] = 2

        # P = {1} (state 2)
        if s_i == '0':
            trans[(2, -1)] = 1
            trans[(2, 0)] = 2
        else:
            trans[(2, -1)] = 1
            trans[(2, 0)] = 3
            trans[(2, 1)] = 2

        # P = {0, 1} (state 3)
        if s_i == '0':
            trans[(3, 0)] = 3
            trans[(3, 1)] = 2
            trans[(3, -1)] = 1
        else:
            trans[(3, -1)] = 1
            trans[(3, 0)] = 3
            trans[(3, 1)] = 3
            trans[(3, 2)] = 2

        # P = {} (state 0)
        # Any v_i leads to {}
        # We'll handle this by only iterating over defined transitions

        return trans

    def get_B_transitions(s_i):
        # States: 0: {}, 1: {0}, 2: {-1}, 3: {0, -1}
        trans = {}

        # P = {0} (state 1)
        if s_i == '0':
            trans[(1, 0)] = 1
            trans[(1, -1)] = 2
        else:
            trans[(1, 0)] = 3
            trans[(1, -1)] = 2
            trans[(1, 1)] = 1

        # P = {-1} (state 2)
        if s_i == '0':
            trans[(2, 1)] = 1
            trans[(2, 0)] = 2
        else:
            trans[(2, 1)] = 3
            trans[(2, 0)] = 2
            trans[(2, 2)] = 1

        # P = {0, -1} (state 3)
        if s_i == '0':
            trans[(3, 0)] = 3
            trans[(3, 1)] = 1
            trans[(3, -1)] = 2
        else:
            trans[(3, -1)] = 2
            trans[(3, 0)] = 3
            trans[(3, 1)] = 3
            trans[(3, 2)] = 1

        return trans

    # DP for A
    dp_A = [0] * 4
    dp_A[1] = 1
    for char in s:
        new_dp = [0] * 4
        trans = get_A_transitions(char)
        # We need to consider all possible v_i.
        # But only v_i in {-1, 0, 1, 2} can lead to a non-empty state.
        for v in range(-1, 3):
            for state in range(1, 4):
                if (state, v) in trans:
                    new_dp[trans[(state, v)]] = (new_dp[trans[(state, v)]] + dp_A[state]) % MOD
        dp_A = new_dp

    ans_A = (dp_A[1] + dp_A[3]) % MOD

    # DP for B
    dp_B = [0] * 4
    dp_B[1] = 1
    for char in s:
        new_dp = [0] * 4
        trans = get_B_transitions(char)
        for v in range(-2, 3):
            for state in range(1, 4):
                if (state, v) in trans:
                    new_dp[trans[(state, v)]] = (new_dp[trans[(state, v)]] + dp_B[state]) % MOD
        dp_B = new_dp

    ans_B = (dp_B[1] + dp_B[3]) % MOD

    # DP for A and B
    dp_AB = {} # (stateA, stateB) -> count
    dp_AB[(1, 1)] = 1
    for char in s:
        new_dp = {}
        trans_A = get_A_transitions(char)
        trans_B = get_B_transitions(char)

        # All possible v_i that could be in both
        all_v = set()
        for k, v in trans_A.items(): all_v.add(v)
        for k, v in trans_B.items(): all_v.add(v)

        for v in all_v:
            for (sA, sB), count in dp_AB.items():
                nextA = trans_A.get((sA, v), 0)
                nextB = trans_B.get((sB, v), 0)
                if nextA != 0 and nextB != 0:
                    new_dp[(nextA, nextB)] = (new_dp.get((nextA, nextB), 0) + count) % MOD
        dp_AB = new_dp

    ans_AB = 0
    for (sA, sB), count in dp_AB.items():
        if sA in (1, 3) and sB in (1, 3):
            ans_AB = (ans_AB + count) % MOD

    return (ans_A + ans_B - ans_AB + MOD) % MOD

