import heapq

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane. """

    is_val = S_x // K
    js_val = S_y // K
    it_val = T_x // K
    jt_val = T_y // K

    if (is_val % 2) == (js_val % 2):
        ks = S_y % K
    else:
        ks = S_x % K

    if (it_val % 2) == (jt_val % 2):
        kt = T_y % K
    else:
        kt = T_x % K

    if is_val == it_val and js_val == jt_val:
        return abs(ks - kt)

    def get_neighbors(i, j, k):
        neighbors = []
        is_h = (i % 2 == j % 2)

        # Internal moves
        if k > 0: neighbors.append((i, j, k - 1, 1))
        if k < K - 1: neighbors.append((i, j, k + 1, 1))

        if is_h:
            # Horizontal block: [iK, (i+1)K] x [jK+k, jK+k+1]
            # Right boundary: adjacent to T_{i+1,j,0} (V)
            neighbors.append((i + 1, j, 0, 1))
            # Left boundary: adjacent to T_{i-1,j,K-1} (V)
            neighbors.append((i - 1, j, K - 1, 1))
            # Top boundary: if k == K-1, adjacent to all T_{i,j+1,k'} (V)
            if k == K - 1:
                neighbors.append((i, j + 1, 0, 1))
                neighbors.append((i, j + 1, K - 1, 1))
                if i == it_val and j + 1 == jt_val:
                    neighbors.append((i, j + 1, kt, 1))
            # Bottom boundary: if k == 0, adjacent to all T_{i,j-1,k'} (V)
            if k == 0:
                neighbors.append((i, j - 1, 0, 1))
                neighbors.append((i, j - 1, K - 1, 1))
                if i == it_val and j - 1 == jt_val:
                    neighbors.append((i, j - 1, kt, 1))
        else:
            # Vertical block: [iK+k, iK+k+1] x [jK, (j+1)K]
            # Top boundary: adjacent to T_{i,j+1,0} (H)
            neighbors.append((i, j + 1, 0, 1))
            # Bottom boundary: adjacent to T_{i,j-1,K-1} (H)
            neighbors.append((i, j - 1, K - 1, 1))
            # Right boundary: if k == K-1, adjacent to all T_{i+1,j,k'} (H)
            if k == K - 1:
                neighbors.append((i + 1, j, 0, 1))
                neighbors.append((i + 1, j, K - 1, 1))
                if i + 1 == it_val and j == jt_val:
                    neighbors.append((i + 1, j, kt, 1))
            # Left boundary: if k == 0, adjacent to all T_{i-1,j,k'} (H)
            if k == 0:
                neighbors.append((i - 1, j, 0, 1))
                neighbors.append((i - 1, j, K - 1, 1))
                if i - 1 == it_val and j == jt_val:
                    neighbors.append((i - 1, j, kt, 1))

        return neighbors

    start_node = (is_val, js_val, ks)
    target_node = (it_val, jt_val, kt)

    # Use Dijkstra for reasonably close blocks
    if abs(is_val - it_val) + abs(js_val - jt_val) < 400:
        pq = [(0, start_node)]
        dist = {start_node: 0}
        while pq:
            d, curr = heapq.heappop(pq)
            if curr == target_node: return d
            if d > dist.get(curr, float('inf')): continue
            i, j, k = curr
            for ni, nj, nk, w in get_neighbors(i, j, k):
                if abs(ni - (is_val + it_val)//2) > 300 or abs(nj - (js_val + jt_val)//2) > 300:
                    continue
                if d + w < dist.get((ni, nj, nk), float('inf')):
                    dist[(ni, nj, nk)] = d + w
                    heapq.heappush(pq, (d + w, (ni, nj, nk)))

    # For far apart blocks, use portal distance
    def get_dist_to_portals(start_i, start_j, start_k):
        pq = [(0, (start_i, start_j, start_k))]
        dist = {(start_i, start_j, start_k): 0}
        portal_dists = {}
        while pq:
            d, curr = heapq.heappop(pq)
            if d > dist.get(curr, float('inf')): continue
            i, j, k = curr
            if k == 0 or k == K - 1:
                portal_dists[(i, j, k)] = min(portal_dists.get((i, j, k), float('inf')), d)
            if abs(i - start_i) > 20 or abs(j - start_j) > 20: continue
            for ni, nj, nk, w in get_neighbors(i, j, k):
                if abs(ni - start_i) > 20 or abs(nj - start_j) > 20: continue
                if d + w < dist.get((ni, nj, nk), float('inf')):
                    dist[(ni, nj, nk)] = d + w
                    heapq.heappush(pq, (d + w, (ni, nj, nk)))
        return portal_dists

    s_portals = get_dist_to_portals(is_val, js_val, ks)
    t_portals = get_dist_to_portals(it_val, jt_val, kt)

    min_total = float('inf')
    for (si, sj, sk), sd in s_portals.items():
        for (ti, tj, tk), td in t_portals.items():
            cost = sd + td + abs(si - ti) + abs(sj - tj)
            min_total = min(min_total, cost)

    return min_total

