def count_in_degree_sequences(n: int, s: str) -> int:
    MOD = 998244353

    # A subset of {0, 1} represented as a bitmask
    # 0: empty, 1: {0}, 2: {1}, 3: {0, 1}

    def get_next_S(S, I):
        next_S = 0
        for u in range(2):
            if (S >> u) & 1:
                for v in range(2):
                    if (v - u) in I:
                        next_S |= (1 << v)
        return next_S

    # Precompute possible I sets for '0' and '1'
    possible_I_0 = [
        {1},       # d_i = 0 -> I = {1}
        {0},       # d_i = 1 -> I = {0}
        {-1},      # d_i = 2 -> I = {-1}
    ]
    possible_I_1 = [
        {1},             # d_i = 0 -> I = {1}
        {0, 1},         # d_i = 1 -> I = {0, 1}
        {-1, 0},        # d_i = 2 -> I = {-1, 0}
        {-1},           # d_i = 3 -> I = {-1}
    ]

    # DP state: (S_0, S_1) where S_0 is set of x_i given x_{-1}=0, S_1 given x_{-1}=1
    # State represented as S_0 * 4 + S_1 (0 to 15)
    dp = [0] * 16
    # Initial state: x_{-1}=0 -> S_0={0}, x_{-1}=1 -> S_1={1}
    dp[1 * 4 + 2] = 1

    for char in s:
        new_dp = [0] * 16
        sets = possible_I_0 if char == '0' else possible_I_1
        for state in range(16):
            if dp[state] == 0:
                continue
            S0, S1 = state // 4, state % 4
            count = dp[state]
            for I in sets:
                next_S0 = get_next_S(S0, I)
                next_S1 = get_next_S(S1, I)
                next_state = next_S0 * 4 + next_S1
                new_dp[next_state] = (new_dp[next_state] + count) % MOD
        dp = new_dp

    ans = 0
    for state in range(16):
        S0, S1 = state // 4, state % 4
        # Condition: (0 in S_n_0) OR (1 in S_n_1)
        if ((S0 >> 0) & 1) or ((S1 >> 1) & 1):
            ans = (ans + dp[state]) % MOD

    return ans

