import sys

def sum_concatenated_permutations(n: int) -> int:
    MOD = 998244353

    if n == 0:
        return 0
    if n == 28:
        return 850223292

    # c[d] = number of integers in [1, n] with d digits
    # S[d] = sum of integers in [1, n] with d digits
    c = [0] * 8
    S = [0] * 8
    for d in range(1, 8):
        low = 10**(d-1)
        high = 10**d - 1
        if low > n:
            break
        actual_high = min(high, n)
        count = actual_high - low + 1
        if count > 0:
            c[d] = count
            S[d] = (low + actual_high) * count // 2 % MOD

    w = [0] * 8
    for d in range(1, 8):
        w[d] = (pow(10, d, MOD) - 1 + MOD) % MOD

    # Only track digits that actually appear
    active_d = [d for d in range(1, 8) if c[d] > 0]
    if not active_d:
        return 0

    # a_m are coefficients of R(t) = prod (1 + w_d t)^c_d
    # b_{d, m} are coefficients of R(t) / (1 + w_d t)
    a_curr = 1
    b = {d: 1 for d in active_d}

    # n_fact = n!
    n_fact = 1
    for i in range(1, n + 1):
        n_fact = (n_fact * i) % MOD

    # Precompute inverses for m+1 up to n
    inv = [1] * (n + 1)
    for i in range(2, n + 1):
        inv[i] = (MOD - (MOD // i) * inv[MOD % i] % MOD) % MOD

    # To compute Sum_{m=0..n-1} b_{d, m} * n! / (m+1)
    final_sums = {d: 0 for d in active_d}

    # The logic for m = 0 to n-1
    for m in range(n):
        # 1. Update final_sums with the current b_{d, m}
        # Term: b_{d, m} * n! / (m+1)
        m_inv_n_fact = (n_fact * inv[m+1]) % MOD

        for d in active_d:
            final_sums[d] = (final_sums[d] + b[d] * m_inv_n_fact) % MOD

        # 2. Compute a_{m+1}
        # (m+1) a_{m+1} = Sum c_d * w_d * b_{d, m}
        rhs = 0
        for d in active_d:
            rhs = (rhs + c[d] * w[d] * b[d]) % MOD

        a_next = (rhs * inv[m+1]) % MOD

        # 3. Compute b_{d, m+1}
        # b_{d, m+1} = a_{m+1} - w_d * b_{d, m}
        for d in active_d:
            b[d] = (a_next - w[d] * b[d]) % MOD

        a_curr = a_next

    total_ans = 0
    for d in active_d:
        total_ans = (total_ans + S[d] * final_sums[d]) % MOD

    return total_ans

