import heapq

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane. """

    is_val = S_x // K
    js_val = S_y // K
    it_val = T_x // K
    jt_val = T_y // K

    if (is_val % 2) == (js_val % 2):
        ks = S_y % K
    else:
        ks = S_x % K

    if (it_val % 2) == (jt_val % 2):
        kt = T_y % K
    else:
        kt = T_x % K

    if is_val == it_val and js_val == jt_val:
        return abs(ks - kt)

    def get_edges(i, j, k):
        edges = []
        is_h = (i % 2 == j % 2)

        if is_h:
            edges.append(((i + 1, j, 0), 1))
            edges.append(((i - 1, j, K - 1), 1))
            if k == K - 1:
                edges.append(((i, j + 1, 0), 1))
                edges.append(((i, j + 1, K - 1), 1))
            if k == 0:
                edges.append(((i, j - 1, 0), 1))
                edges.append(((i, j - 1, K - 1), 1))
        else:
            edges.append(((i, j + 1, 0), 1))
            edges.append(((i, j - 1, K - 1), 1))
            if k == K - 1:
                edges.append(((i + 1, j, 0), 1))
                edges.append(((i + 1, j, K - 1), 1))
            if k == 0:
                edges.append(((i - 1, j, 0), 1))
                edges.append(((i - 1, j, K - 1), 1))

        return edges

    start_node = (is_val, js_val, ks)
    target_node = (it_val, jt_val, kt)

    if abs(is_val - it_val) + abs(js_val - jt_val) > 1000:
        def get_portal_dists(start_i, start_j, start_k):
            pq = [(0, (start_i, start_j, start_k))]
            dist = {(start_i, start_j, start_k): 0}
            portals = {}
            while pq:
                d, curr = heapq.heappop(pq)
                if d > dist.get(curr, float('inf')): continue
                i, j, k = curr
                if k == 0 or k == K - 1:
                    portals[(i, j, k)] = min(portals.get((i, j, k), float('inf')), d)
                if abs(i - start_i) > 15 or abs(j - start_j) > 15: continue

                if k != 0:
                    cost = k
                    if d + cost < dist.get((i, j, 0), float('inf')):
                        dist[(i, j, 0)] = d + cost
                        heapq.heappush(pq, (d + cost, (i, j, 0)))
                if k != K - 1:
                    cost = (K - 1) - k
                    if d + cost < dist.get((i, j, K - 1), float('inf')):
                        dist[(i, j, K - 1)] = d + cost
                        heapq.heappush(pq, (d + cost, (i, j, K - 1)))

                for next_node, weight in get_edges(i, j, k):
                    ni, nj, nk = next_node
                    if abs(ni - start_i) > 15 or abs(nj - start_j) > 15: continue
                    if d + weight < dist.get(next_node, float('inf')):
                        dist[next_node] = d + weight
                        heapq.heappush(pq, (d + weight, next_node))
            return portals

        s_portals = get_portal_dists(is_val, js_val, ks)
        t_portals = get_portal_dists(it_val, jt_val, kt)

        res = float('inf')
        for (si, sj, sk), sd in s_portals.items():
            for (ti, tj, tk), td in t_portals.items():
                res = min(res, sd + td + abs(si - ti) + abs(sj - tj))
        return res

    pq = [(0, start_node)]
    dist = {start_node: 0}
    while pq:
        d, curr = heapq.heappop(pq)
        if curr == target_node: return d
        if d > dist.get(curr, float('inf')): continue
        i, j, k = curr

        if k != 0:
            cost = k
            if d + cost < dist.get((i, j, 0), float('inf')):
                dist[(i, j, 0)] = d + cost
                heapq.heappush(pq, (d + cost, (i, j, 0)))
        if k != K - 1:
            cost = (K - 1) - k
            if d + cost < dist.get((i, j, K - 1), float('inf')):
                dist[(i, j, K - 1)] = d + cost
                heapq.heappush(pq, (d + cost, (i, j, K - 1)))

        for next_node, weight in get_edges(i, j, k):
            ni, nj, nk = next_node
            if ni == it_val and nj == jt_val:
                actual_weight = weight + abs(nk - kt)
                if d + actual_weight < dist.get(target_node, float('inf')):
                    dist[target_node] = d + actual_weight
                    heapq.heappush(pq, (d + actual_weight, target_node))

            if d + weight < dist.get(next_node, float('inf')):
                dist[next_node] = d + weight
                heapq.heappush(pq, (d + weight, next_node))
    return dist.get(target_node, float('inf'))
